beforeExample:
package test;

import java.net.MalformedURLException;
import java.net.URL;
import org.eclipse.jdt.internal.ui.actions.OpenBrowserUtil;
import org.eclipse.swt.widgets.Display;

public class Example {
    public void someMethod(URL url, Display display) throws MalformedURLException {
        // Example calls to the deprecated method
        OpenBrowserUtil.open(new URL("http://example.com/page1"), display, "Page One");
        OpenBrowserUtil.open(url, Display.getDefault(), "Default Display Page");
    }
}

