negativeExample:
package test;

import java.net.MalformedURLException;
import java.net.URL;
import org.eclipse.jdt.internal.ui.actions.OpenBrowserUtil;
import org.eclipse.swt.widgets.Display;

public class NegativeExample {
    public void someMethod(URL url, Display display) throws MalformedURLException {
        // This method call should not be transformed as it already uses the correct signature
        OpenBrowserUtil.open(url, display);
        // Another method call from a different class should also not be transformed
        someOtherClass.staticMethod(url, display, "Title");
    }

    static class someOtherClass {
        public static void staticMethod(URL url, Display display, String title) { }
    }
}
